// generated by scripts/build-panel.mjs -- do not edit by hand
export const PANEL_HTML = "<!doctype html>\n<html lang=\"fa\" dir=\"rtl\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1,viewport-fit=cover\">\n<title>پنل مدیریت</title>\n<script src=\"https://telegram.org/js/telegram-web-app.js\"></script>\n<style>\n:root{--bg:var(--tg-theme-bg-color,#fff);--fg:var(--tg-theme-text-color,#111);--hint:var(--tg-theme-hint-color,#7a7a7a);--btn:var(--tg-theme-button-color,#2481cc);--btnfg:var(--tg-theme-button-text-color,#fff);--sec:var(--tg-theme-secondary-bg-color,#f1f1f2);--red:#d33;--green:#2a9d4a}\n*{box-sizing:border-box}\nbody{margin:0;background:var(--bg);color:var(--fg);font:15px/1.5 system-ui,-apple-system,\"Segoe UI\",Tahoma,sans-serif;padding-bottom:84px}\n#app{padding:14px}\nh3{margin:18px 0 8px;font-size:15px}\n.hint{color:var(--hint)} .err{color:var(--red)}\n.grid{display:grid;grid-template-columns:1fr 1fr;gap:10px}\n.card{background:var(--sec);border-radius:12px;padding:12px;display:flex;flex-direction:column;gap:2px}\n.card b{font-size:20px}\n.row{background:var(--sec);border-radius:12px;padding:10px 12px;margin-bottom:8px;display:flex;justify-content:space-between;align-items:center;gap:8px}\n.row .t{flex:1;min-width:0}\n.row .t div{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n.row small{color:var(--hint)}\n.badge{font-size:12px;padding:2px 8px;border-radius:99px;background:var(--bg);color:var(--hint);white-space:nowrap}\n.badge.ok{color:var(--green)} .badge.low{color:var(--red)}\nbutton{border:0;border-radius:10px;padding:9px 14px;background:var(--btn);color:var(--btnfg);font:inherit;cursor:pointer}\nbutton.ghost{background:var(--sec);color:var(--fg)}\nbutton.danger{background:var(--red);color:#fff}\nbutton.sm{padding:5px 10px;font-size:13px}\ninput,select,textarea{width:100%;padding:9px 10px;border-radius:10px;border:1px solid var(--sec);background:var(--sec);color:var(--fg);font:inherit;margin:4px 0 10px}\ntextarea{min-height:80px}\nlabel{font-size:13px;color:var(--hint)}\n.bar{display:flex;gap:8px;margin-bottom:10px}\n.bar input{margin:0}\n#tabs{position:fixed;bottom:0;left:0;right:0;display:flex;background:var(--sec);padding:6px 4px calc(6px + env(safe-area-inset-bottom))}\n#tabs button{flex:1;background:none;color:var(--hint);padding:4px 2px;font-size:11px;display:flex;flex-direction:column;align-items:center;gap:2px}\n#tabs button span{font-size:19px}\n#tabs button.on{color:var(--btn)}\n#modal{position:fixed;inset:0;background:rgba(0,0,0,.45);display:flex;align-items:flex-end;z-index:10}\n#modal.hidden{display:none}\n#sheet{background:var(--bg);width:100%;max-height:92vh;overflow:auto;border-radius:18px 18px 0 0;padding:16px 16px calc(16px + env(safe-area-inset-bottom))}\n#toast{position:fixed;top:12px;left:50%;transform:translateX(-50%);background:#222;color:#fff;padding:8px 14px;border-radius:99px;opacity:0;pointer-events:none;transition:.2s;z-index:20}\n#toast.on{opacity:1}\n</style>\n</head>\n<body>\n<div id=\"app\"></div>\n<nav id=\"tabs\"></nav>\n<div id=\"modal\" class=\"hidden\"><div id=\"sheet\"></div></div>\n<div id=\"toast\"></div>\n<script>\nconst T = \"__TENANT__\";\nconst tg = window.Telegram && window.Telegram.WebApp;\nif (tg) { tg.ready(); tg.expand(); }\nconst $ = (s) => document.querySelector(s);\nconst esc = (s) => String(s == null ? \"\" : s).replace(/[&<>\"']/g, (c) => ({ \"&\": \"&amp;\", \"<\": \"&lt;\", \">\": \"&gt;\", '\"': \"&quot;\", \"'\": \"&#39;\" }[c]));\nconst usd = (c) => \"$\" + (c / 100).toFixed(2);\nconst when = (t) => new Date(t * 1000).toLocaleString(\"fa-IR\");\n\nasync function api(method, path, body) {\n  const r = await fetch(\"/api/\" + T + path, {\n    method,\n    headers: { \"content-type\": \"application/json\", \"X-Init-Data\": tg ? tg.initData : \"\" },\n    body: body ? JSON.stringify(body) : undefined,\n  });\n  const j = await r.json().catch(() => ({}));\n  if (!r.ok) throw new Error(j.error || \"خطا \" + r.status);\n  return j;\n}\nfunction toast(m) { const t = $(\"#toast\"); t.textContent = m; t.classList.add(\"on\"); setTimeout(() => t.classList.remove(\"on\"), 2400); }\nfunction openModal(html) { $(\"#sheet\").innerHTML = html; $(\"#modal\").classList.remove(\"hidden\"); }\nfunction closeModal() { $(\"#modal\").classList.add(\"hidden\"); }\n$(\"#modal\").addEventListener(\"click\", (e) => { if (e.target.id === \"modal\") closeModal(); });\nasync function act(fn, ok) { try { const r = await fn(); if (ok) toast(typeof ok === \"function\" ? ok(r) : ok); } catch (e) { toast(e.message); } }\n\nlet tab = \"overview\";\nlet cats = [];\nlet products = [];\nconst TABS = [[\"overview\", \"📊\", \"نمای کلی\"], [\"products\", \"📦\", \"محصولات\"], [\"categories\", \"🗂\", \"دسته‌ها\"], [\"deposits\", \"💳\", \"شارژها\"], [\"settings\", \"⚙️\", \"تنظیمات\"]];\n\nfunction renderTabs() {\n  $(\"#tabs\").innerHTML = TABS.map(([k, i, l]) => `<button class=\"${k === tab ? \"on\" : \"\"}\" data-k=\"${k}\"><span>${i}</span>${l}</button>`).join(\"\");\n  document.querySelectorAll(\"#tabs button\").forEach((b) => (b.onclick = () => go(b.dataset.k)));\n}\nasync function go(k) {\n  tab = k; renderTabs();\n  $(\"#app\").innerHTML = '<p class=\"hint\">در حال بارگذاری…</p>';\n  try { await views[k](); } catch (e) { $(\"#app\").innerHTML = `<p class=\"err\">${esc(e.message)}</p>`; }\n}\n\nconst catOptions = (sel) => '<option value=\"\">— بدون دسته —</option>' + cats.map((c) => `<option value=\"${c.id}\" ${String(c.id) === String(sel) ? \"selected\" : \"\"}>${esc(c.title)}</option>`).join(\"\");\n\nfunction productModal(p) {\n  openModal(`<h3>${p ? \"ویرایش محصول\" : \"محصول جدید\"}</h3>\n    <label>نام</label><input id=\"f_title\" value=\"${esc(p ? p.title : \"\")}\">\n    <label>قیمت (دلار)</label><input id=\"f_price\" inputmode=\"decimal\" value=\"${p ? p.price_cents / 100 : \"\"}\">\n    <label>دسته</label><select id=\"f_cat\">${catOptions(p ? p.category_id : \"\")}</select>\n    <label>توضیحات</label><textarea id=\"f_desc\">${esc(p ? p.description : \"\")}</textarea>\n    ${p ? `<label><input type=\"checkbox\" id=\"f_active\" ${p.is_active ? \"checked\" : \"\"} style=\"width:auto;margin:0 0 0 6px\">فعال</label>` : \"\"}\n    <div class=\"bar\" style=\"margin-top:12px\"><button id=\"save\">ذخیره</button><button class=\"ghost\" id=\"cancel\">بستن</button></div>\n    ${p ? `<h3>افزودن موجودی (هر خط یک آیتم)</h3><textarea id=\"f_items\" placeholder=\"email:password یا کد\"></textarea><button id=\"addItems\">افزودن آیتم‌ها</button><p class=\"hint\">موجودی فعلی: ${p.avail} · فروخته‌شده: ${p.sold}</p>` : \"\"}`);\n  $(\"#cancel\").onclick = closeModal;\n  $(\"#save\").onclick = () => act(async () => {\n    const body = { title: $(\"#f_title\").value.trim(), price_usd: Number($(\"#f_price\").value.replace(\",\", \".\")), category_id: $(\"#f_cat\").value ? Number($(\"#f_cat\").value) : null, description: $(\"#f_desc\").value.trim() || null };\n    if (p) { body.is_active = $(\"#f_active\").checked ? 1 : 0; await api(\"PATCH\", \"/products/\" + p.id, body); } else await api(\"POST\", \"/products\", body);\n    closeModal(); go(\"products\");\n  }, \"ذخیره شد\");\n  if (p) $(\"#addItems\").onclick = () => act(async () => {\n    const r = await api(\"POST\", \"/products/\" + p.id + \"/items\", { text: $(\"#f_items\").value });\n    closeModal(); go(\"products\"); return r;\n  }, (r) => r.added + \" آیتم اضافه شد\");\n}\n\nfunction categoryModal(c) {\n  openModal(`<h3>${c ? \"ویرایش دسته\" : \"دسته جدید\"}</h3>\n    <label>نام</label><input id=\"g_title\" value=\"${esc(c ? c.title : \"\")}\">\n    <label>دسته‌ی والد</label><select id=\"g_parent\">${catOptions(c ? c.parent_id : \"\")}</select>\n    <label>ترتیب نمایش (عدد کوچک‌تر بالاتر)</label><input id=\"g_sort\" inputmode=\"numeric\" value=\"${c ? c.sort : 0}\">\n    ${c ? `<label><input type=\"checkbox\" id=\"g_active\" ${c.is_active ? \"checked\" : \"\"} style=\"width:auto;margin:0 0 0 6px\">فعال</label>` : \"\"}\n    <div class=\"bar\" style=\"margin-top:12px\"><button id=\"save\">ذخیره</button><button class=\"ghost\" id=\"cancel\">بستن</button></div>`);\n  $(\"#cancel\").onclick = closeModal;\n  $(\"#save\").onclick = () => act(async () => {\n    const body = { title: $(\"#g_title\").value.trim(), parent_id: $(\"#g_parent\").value ? Number($(\"#g_parent\").value) : null, sort: Number($(\"#g_sort\").value) || 0 };\n    if (c) { body.is_active = $(\"#g_active\").checked ? 1 : 0; await api(\"PATCH\", \"/categories/\" + c.id, body); } else await api(\"POST\", \"/categories\", body);\n    closeModal(); go(\"categories\");\n  }, \"ذخیره شد\");\n}\n\nconst DEP_LABEL = { awaiting: \"در انتظار پرداخت\", pending_review: \"نیاز به بررسی\", paid: \"پرداخت‌شده\", rejected: \"ردشده\", expired: \"منقضی\" };\nconst FIELDS = [[\"card_number\", \"شماره کارت (خالی = غیرفعال)\"], [\"card_holder\", \"نام صاحب کارت\"], [\"usdt_trc20_address\", \"آدرس USDT TRC20 (خالی = غیرفعال)\"], [\"min_deposit_usd\", \"حداقل شارژ (دلار)\"], [\"referral_percent\", \"درصد پاداش دعوت (۰ = غیرفعال)\"], [\"usd_to_toman\", \"نرخ دلار (تومان)\"], [\"support_hours\", \"ساعت پاسخگویی پشتیبانی\"], [\"welcome_text\", \"متن خوش‌آمدگویی\"]];\n\nconst views = {\n  async overview() {\n    const d = await api(\"GET\", \"/overview\");\n    $(\"#app\").innerHTML = `<div class=\"grid\">\n      <div class=\"card\"><b>${d.users}</b><span class=\"hint\">کاربران</span></div>\n      <div class=\"card\"><b>${d.orders}</b><span class=\"hint\">سفارش‌ها</span></div>\n      <div class=\"card\"><b>${usd(d.revenue_cents)}</b><span class=\"hint\">مجموع فروش</span></div>\n      <div class=\"card\"><b>${d.pending_deposits}</b><span class=\"hint\">شارژ در انتظار بررسی</span></div></div>\n      <h3>کمترین موجودی</h3>\n      ${d.low_stock.map((p) => `<div class=\"row\"><div class=\"t\"><div>${esc(p.title)}</div></div><span class=\"badge ${p.avail > 2 ? \"ok\" : \"low\"}\">${p.avail} عدد</span></div>`).join(\"\") || '<p class=\"hint\">محصولی نیست.</p>'}\n      <h3>آخرین سفارش‌ها</h3>\n      ${d.recent_orders.map((o) => `<div class=\"row\"><div class=\"t\"><div>#${o.id} ${esc(o.title)}</div><small>${esc(o.user_id)} · ${when(o.created_at)}</small></div><span class=\"badge\">${usd(o.price_cents)}</span></div>`).join(\"\") || '<p class=\"hint\">سفارشی نیست.</p>'}`;\n  },\n  async products() {\n    const [p, c] = await Promise.all([api(\"GET\", \"/products\"), api(\"GET\", \"/categories\")]);\n    products = p.products; cats = c.categories;\n    $(\"#app\").innerHTML = '<div class=\"bar\"><input id=\"q\" placeholder=\"جستجو…\"><button id=\"add\">＋ محصول</button></div><div id=\"list\"></div>';\n    const draw = () => {\n      const q = $(\"#q\").value.trim().toLowerCase();\n      $(\"#list\").innerHTML = products.filter((x) => !q || x.title.toLowerCase().includes(q)).map((x) => `<div class=\"row\" data-id=\"${x.id}\"><div class=\"t\"><div>${esc(x.title)}${x.is_active ? \"\" : \" ⛔\"}</div><small>${usd(x.price_cents)} · فروش ${x.sold}</small></div><span class=\"badge ${x.avail > 2 ? \"ok\" : \"low\"}\">${x.avail} عدد</span></div>`).join(\"\") || '<p class=\"hint\">محصولی نیست.</p>';\n      document.querySelectorAll(\"#list .row\").forEach((r) => (r.onclick = () => productModal(products.find((x) => String(x.id) === r.dataset.id))));\n    };\n    $(\"#q\").oninput = draw; $(\"#add\").onclick = () => productModal(null); draw();\n  },\n  async categories() {\n    const c = await api(\"GET\", \"/categories\");\n    cats = c.categories;\n    const name = (id) => { const x = cats.find((y) => y.id === id); return x ? x.title : \"\"; };\n    $(\"#app\").innerHTML = '<div class=\"bar\"><button id=\"add\">＋ دسته جدید</button></div>' + (cats.map((x) => `<div class=\"row\" data-id=\"${x.id}\"><div class=\"t\"><div>${esc(x.title)}${x.is_active ? \"\" : \" ⛔\"}</div><small>${x.parent_id ? \"زیرمجموعه‌ی \" + esc(name(x.parent_id)) : \"دسته‌ی اصلی\"}</small></div></div>`).join(\"\") || '<p class=\"hint\">دسته‌ای نیست.</p>');\n    $(\"#add\").onclick = () => categoryModal(null);\n    document.querySelectorAll(\".row[data-id]\").forEach((r) => (r.onclick = () => categoryModal(cats.find((x) => String(x.id) === r.dataset.id))));\n  },\n  async deposits() {\n    const d = await api(\"GET\", \"/deposits\");\n    $(\"#app\").innerHTML = `<h3>شارژ دستی کاربر</h3>\n      <label>آیدی عددی تلگرام کاربر</label><input id=\"c_uid\" inputmode=\"numeric\">\n      <label>مبلغ (دلار)</label><input id=\"c_amt\" inputmode=\"decimal\">\n      <button id=\"c_go\">شارژ کیف پول</button>\n      <h3>درخواست‌های شارژ</h3><p class=\"hint\">برای دیدن عکس رسید، پیام همان درخواست را در چت ربات ببینید.</p>\n      ${d.deposits.map((x) => `<div class=\"row\"><div class=\"t\"><div>${esc(x.first_name || \"\")} ${x.username ? \"@\" + esc(x.username) : \"\"} <small>(${esc(x.user_id)})</small></div><small>${x.method === \"card\" ? \"کارت\" : \"USDT\"} · ${usd(x.amount_cents)} · ${DEP_LABEL[x.status] || esc(x.status)}</small></div>${x.status === \"pending_review\" ? `<button class=\"sm\" data-a=\"approve\" data-id=\"${x.id}\">✅</button><button class=\"sm danger\" data-a=\"reject\" data-id=\"${x.id}\">❌</button>` : \"\"}</div>`).join(\"\") || '<p class=\"hint\">درخواستی نیست.</p>'}`;\n    $(\"#c_go\").onclick = () => act(async () => {\n      await api(\"POST\", \"/users/\" + Number($(\"#c_uid\").value) + \"/credit\", { amount_usd: Number($(\"#c_amt\").value.replace(\",\", \".\")) });\n      go(\"deposits\");\n    }, \"کیف پول شارژ شد\");\n    document.querySelectorAll(\"button[data-a]\").forEach((b) => (b.onclick = () => act(async () => {\n      await api(\"POST\", \"/deposits/\" + b.dataset.id + \"/\" + b.dataset.a);\n      go(\"deposits\");\n    }, b.dataset.a === \"approve\" ? \"تأیید شد\" : \"رد شد\")));\n  },\n  async settings() {\n    const s = await api(\"GET\", \"/settings\");\n    $(\"#app\").innerHTML = FIELDS.map(([k, l]) => `<label>${l}</label>` + (k === \"welcome_text\" ? `<textarea id=\"s_${k}\">${esc(s[k] || \"\")}</textarea>` : `<input id=\"s_${k}\" value=\"${esc(s[k] == null ? \"\" : s[k])}\">`)).join(\"\") + '<button id=\"s_save\">ذخیره تنظیمات</button>';\n    $(\"#s_save\").onclick = () => act(async () => {\n      const body = {};\n      FIELDS.forEach(([k]) => (body[k] = $(\"#s_\" + k).value.trim()));\n      await api(\"POST\", \"/settings\", body);\n    }, \"تنظیمات ذخیره شد\");\n  },\n};\n\nif (!tg || !tg.initData) {\n  $(\"#app\").innerHTML = '<p class=\"err\">این پنل فقط داخل تلگرام (از دکمه‌ی «پنل» ربات) باز می‌شود.</p>';\n} else {\n  go(\"overview\");\n}\n</script>\n</body>\n</html>\n";
